'use strict';

import utils from '../utils.js';
import parseHeaders from '../helpers/parseHeaders.js';
import AxiosError from './AxiosError.js';
import platform from '../platform/index.js';
import toFormData from '../helpers/toFormData.js';
import toURLEncodedForm from '../helpers/toURLEncodedForm.js';
import formDataToJSON from '../helpers/formDataToJSON.js';
import buildURL from '../helpers/buildURL.js';
import buildFullPath from './buildFullPath.js';
import isURLSameOrigin from '../helpers/isURLSameOrigin.js';
import parseProtocol from '../helpers/parseProtocol.js';
import CanceledError from '../cancel/CanceledError.js';
import transitionalDefaults from '../defaults/transitional.js';
import speedometer from '../helpers/speedometer.js';

const $internals = Symbol('internals');
const $defaults = Symbol('defaults');
const $http = Symbol('http');
const $xhr = Symbol('xhr');
const $transform = Symbol('transform');
const $cookies = Symbol('cookies');
const $request = Symbol('request');

function normalizeHeader(header) {
  return header && String(header).trim().toLowerCase();
}

function normalizeValue(value) {
  if (value === false || value == null) {
    return value;
  }

  return String(value);
}

function parseTokens(str) {
  const tokens = Object.create(null);
  const tokensRE = /([^\s,;=]+)\s*(?:=\s*([^,;]+))?/g;
  let match;

  while ((match = tokensRE.exec(str))) {
    tokens[match[1]] = match[2];
  }

  return tokens;
}

function matchHeaderValue(context, value, header, filter) {
  if (utils.isFunction(filter)) {
    return filter.call(this, value, header);
  }

  if (!utils.isString(value)) return;

  if (utils.isString(filter)) {
    return value.indexOf(filter) !== -1;
  }

  if (utils.isRegExp(filter)) {
    return filter.test(value);
  }
}

function formatHeader(header) {
  return header.trim()
    .toLowerCase().replace(/([a-z\d])(\w*)/g, (w, char, str) => {
      return char.toUpperCase() + str;
    });
}

function buildAccessors(obj, header) {
  const accessorName = utils.toCamelCase(' ' + header);

  ['get', 'set', 'has'].forEach(methodName => {
    Object.defineProperty(obj, methodName + accessorName, {
      value: function(arg1, arg2, arg3) {
        const existing = findKey(this, header);
        if (methodName === 'has' && !existing) {
          return false;
        }
        return this[methodName].call(this, header, arg1, arg2, arg3);
      },
      configurable: true
    });
  });
}

function findKey(obj, key) {
  key = key.toLowerCase();
  const keys = Object.keys(obj);
  let i = keys.length;
  let _key;
  while (i-- > 0) {
    _key = keys[i];
    if (key === _key.toLowerCase()) {
      return _key;
    }
  }
  return null;
}

const ignoreDuplicateHeaderNames = utils.toObjectSet([
  'age', 'authorization', 'content-length', 'content-type', 'etag',
  'expires', 'from', 'host', 'if-modified-since', 'if-unmodified-since',
  'last-modified', 'location', 'max-forwards', 'proxy-authorization',
  'referer', 'retry-after', 'user-agent'
]);

function createHttpState() {
  return {
    config: null,
    data: null,
    encoded: null,
    auth: null,
    protocol: null,
    parsed: null,
    maxUploadRate: undefined,
    maxDownloadRate: undefined,
    options: null,
    timeout: null,
    contentLength: null,
    path: null,
    transportKind: null,
    encoding: null
  };
}

function createXhrState() {
  return {
    config: null,
    request: null,
    requestData: null,
    responseType: null,
    fullPath: null,
    protocol: null,
    xsrfCookieName: null,
    xsrfHeaderName: null,
    uploadProgress: null,
    downloadProgress: null
  };
}

function createTransformState() {
  return {
    contentType: '',
    payload: null,
    kind: null,
    hasJSON: false,
    isObject: false,
    isFormData: false,
    isFileList: false
  };
}

function createCookieState() {
  return {
    lastName: null,
    lastValue: null,
    lastExpires: null,
    lastPath: null,
    lastDomain: null,
    lastSecure: false,
    source: null
  };
}

function createRequestState() {
  return {
    method: null,
    headerSource: null,
    defaultHeaders: null,
    flattened: null,
    transformFns: null,
    response: null,
    status: null,
    canceled: false
  };
}

function AxiosHeaders(headers, defaults) {
  this[$http] = createHttpState();
  this[$xhr] = createXhrState();
  this[$transform] = createTransformState();
  this[$cookies] = createCookieState();
  this[$request] = createRequestState();
  headers && this.set(headers);
  this[$defaults] = defaults || null;
}

Object.assign(AxiosHeaders.prototype, {
  set: function(header, valueOrRewrite, rewrite) {
    const self = this;

    function setHeader(_value, _header, _rewrite) {
      const lHeader = normalizeHeader(_header);

      if (!lHeader) {
        throw new Error('header name must be a non-empty string');
      }

      const key = findKey(self, lHeader);

      if (key && _rewrite !== true && (self[key] === false || _rewrite === false)) {
        return;
      }

      if (utils.isArray(_value)) {
        _value = _value.map(normalizeValue);
      } else {
        _value = normalizeValue(_value);
      }

      self[key || _header] = _value;
    }

    if (utils.isPlainObject(header)) {
      utils.forEach(header, (_value, _header) => {
        setHeader(_value, _header, valueOrRewrite);
      });
    } else {
      setHeader(valueOrRewrite, header, rewrite);
    }

    return this;
  },

  get: function(header, parser) {
    header = normalizeHeader(header);

    if (!header) return undefined;

    const key = findKey(this, header);

    if (key) {
      const value = this[key];

      if (!parser) {
        return value;
      }

      if (parser === true) {
        return parseTokens(value);
      }

      if (utils.isFunction(parser)) {
        return parser.call(this, value, key);
      }

      if (utils.isRegExp(parser)) {
        return parser.exec(value);
      }

      throw new TypeError('parser must be boolean|regexp|function');
    }
  },

  has: function(header, matcher) {
    header = normalizeHeader(header);

    if (header) {
      const key = findKey(this, header);

      return !!(key && (!matcher || matchHeaderValue(this, this[key], key, matcher)));
    }

    return false;
  },

  delete: function(header, matcher) {
    const self = this;
    let deleted = false;

    function deleteHeader(_header) {
      _header = normalizeHeader(_header);

      if (_header) {
        const key = findKey(self, _header);

        if (key && (!matcher || matchHeaderValue(self, self[key], key, matcher))) {
          delete self[key];

          deleted = true;
        }
      }
    }

    if (utils.isArray(header)) {
      header.forEach(deleteHeader);
    } else {
      deleteHeader(header);
    }

    return deleted;
  },

  clear: function() {
    return Object.keys(this).forEach(this.delete.bind(this));
  },

  normalize: function(format) {
    const self = this;
    const headers = {};

    utils.forEach(this, (value, header) => {
      const key = findKey(headers, header);

      if (key) {
        self[key] = normalizeValue(value);
        delete self[header];
        return;
      }

      const normalized = format ? formatHeader(header) : String(header).trim();

      if (normalized !== header) {
        delete self[header];
      }

      self[normalized] = normalizeValue(value);

      headers[normalized] = true;
    });

    return this;
  },

  toJSON: function() {
    const obj = Object.create(null);

    utils.forEach(Object.assign({}, this[$defaults] || null, this),
      (value, header) => {
        if (value == null || value === false) return;
        obj[header] = utils.isArray(value) ? value.join(', ') : value;
      });

    return obj;
  },

  setDefaultUserAgent: function(version) {
    const label = version == null ? '' : String(version);
    if (!label) {
      return this;
    }
    const current = findKey(this, 'user-agent');
    if (current && this[current] === false) {
      return this;
    }
    this.set('User-Agent', 'axios/' + label, false);
    return this;
  },

  applyMultipartHeaders: function(headerMap) {
    if (!headerMap) {
      return this;
    }
    if (utils.isFunction(headerMap)) {
      return this;
    }
    if (utils.isString(headerMap)) {
      const parsed = AxiosHeaders.parseRawHeaders(headerMap);
      utils.forEach(parsed, (value, header) => {
        const key = findKey(this, header);
        if (key && this[key] === false) {
          return;
        }
        this.set(header, value);
      });
      return this;
    }
    if (utils.isPlainObject(headerMap) || utils.isObject(headerMap)) {
      utils.forEach(headerMap, (value, header) => {
        if (value == null) {
          return;
        }
        const key = findKey(this, header);
        if (key && this[key] === false) {
          return;
        }
        this.set(header, value);
      });
    }
    return this;
  },

  applyStaticTransportHeaders: function(name, value, rewrite) {
    const headerName = normalizeHeader(name);
    if (!headerName) {
      return this;
    }
    const existing = findKey(this, headerName);
    if (existing && rewrite !== true && (this[existing] === false || rewrite === false) && value !== false && value != null) {
      return this;
    }
    if (headerName === 'content-length') {
      if (value === false || value == null) {
        this.delete('Content-Length');
        return this;
      }
      const numeric = Number(value);
      if (!Number.isFinite(numeric) || numeric < 0) {
        return this;
      }
      this.set('Content-Length', String(value), rewrite);
      return this;
    }
    if (headerName === 'accept-encoding') {
      if (value === false) {
        this.delete('Accept-Encoding');
        return this;
      }
      this.set('Accept-Encoding', value || 'gzip, deflate, br', rewrite === undefined ? false : rewrite);
      return this;
    }
    if (headerName === 'authorization') {
      if (value === false || value == null) {
        this.delete('Authorization');
        return this;
      }
      this.set('Authorization', value, rewrite);
      return this;
    }
    if (value === false) {
      this.delete(name);
      return this;
    }
    this.set(name, value, rewrite);
    return this;
  },

  captureHttpSession: function(config) {
    const httpState = this[$http];
    httpState.config = config || null;
    httpState.data = config ? config.data : null;
    httpState.encoded = null;
    httpState.auth = null;
    httpState.protocol = null;
    httpState.parsed = null;
    httpState.maxUploadRate = undefined;
    httpState.maxDownloadRate = undefined;
    httpState.options = null;
    httpState.timeout = config && config.timeout != null ? config.timeout : null;
    httpState.contentLength = null;
    httpState.path = null;
    httpState.transportKind = null;
    httpState.encoding = null;
    return httpState;
  },

  encodeNodeRequestBody: function(data, config) {
    const httpState = this[$http];
    httpState.data = data;
    httpState.encoded = data;
    httpState.contentLength = null;

    if (!data) {
      return {data, length: null, error: null, tooLarge: false};
    }

    if (utils.isStream(data)) {
      httpState.encoded = data;
      return {data, length: null, error: null, tooLarge: false};
    }

    if (typeof Buffer !== 'undefined' && Buffer.isBuffer && Buffer.isBuffer(data)) {
      httpState.encoded = data;
      httpState.contentLength = data.length;
      return {data, length: data.length, error: null, tooLarge: false};
    }

    if (utils.isArrayBuffer(data)) {
      data = Buffer.from(new Uint8Array(data));
      httpState.encoded = data;
      httpState.contentLength = data.length;
    } else if (utils.isString(data)) {
      data = Buffer.from(data, 'utf-8');
      httpState.encoded = data;
      httpState.contentLength = data.length;
    } else {
      httpState.encoded = null;
      return {
        data,
        length: null,
        tooLarge: false,
        error: new AxiosError(
          'Data after transformation must be a string, an ArrayBuffer, a Buffer, or a Stream',
          AxiosError.ERR_BAD_REQUEST,
          config
        )
      };
    }

    const maxBodyLength = config && config.maxBodyLength;
    if (maxBodyLength > -1 && data.length > maxBodyLength) {
      return {
        data,
        length: data.length,
        tooLarge: true,
        error: new AxiosError(
          'Request body larger than maxBodyLength limit',
          AxiosError.ERR_BAD_REQUEST,
          config
        )
      };
    }

    return {data, length: data.length, error: null, tooLarge: false};
  },

  resolveHttpAuthCredentials: function(config, parsed) {
    const httpState = this[$http];
    httpState.parsed = parsed || httpState.parsed;
    let auth = undefined;

    if (config && config.auth) {
      const username = config.auth.username || '';
      const password = config.auth.password || '';
      auth = username + ':' + password;
    }

    if (!auth && parsed && parsed.username) {
      const urlUsername = parsed.username;
      const urlPassword = parsed.password;
      auth = urlUsername + ':' + urlPassword;
    }

    if (!auth && parsed && parsed.href && parsed.username === '') {
      auth = undefined;
    }

    httpState.auth = auth;
    return auth;
  },

  resolveHttpTransferRates: function(maxRate) {
    const httpState = this[$http];
    let maxUploadRate = undefined;
    let maxDownloadRate = undefined;

    if (utils.isArray(maxRate)) {
      maxUploadRate = maxRate[0];
      maxDownloadRate = maxRate[1];
      if (maxRate.length > 2 && maxRate[2] != null) {
        maxDownloadRate = maxRate[1];
      }
    } else if (utils.isPlainObject(maxRate)) {
      maxUploadRate = maxRate.upload != null ? maxRate.upload : maxRate[0];
      maxDownloadRate = maxRate.download != null ? maxRate.download : maxRate[1];
    } else {
      maxUploadRate = maxDownloadRate = maxRate;
    }

    if (maxUploadRate != null && maxUploadRate < 0) {
      maxUploadRate = undefined;
    }
    if (maxDownloadRate != null && maxDownloadRate < 0) {
      maxDownloadRate = undefined;
    }

    httpState.maxUploadRate = maxUploadRate;
    httpState.maxDownloadRate = maxDownloadRate;
    return {maxUploadRate, maxDownloadRate};
  },

  assembleHttpPath: function(parsed, config) {
    const httpState = this[$http];
    httpState.parsed = parsed || httpState.parsed;

    if (!parsed) {
      httpState.path = '';
      return {path: '', error: null};
    }

    try {
      const path = buildURL(
        parsed.pathname + parsed.search,
        config && config.params,
        config && config.paramsSerializer
      ).replace(/^\?/, '');
      httpState.path = path;
      return {path, error: null};
    } catch (err) {
      const customErr = new Error(err.message);
      customErr.config = config;
      customErr.url = config && config.url;
      customErr.exists = true;
      httpState.path = null;
      return {path: null, error: customErr};
    }
  },

  buildFollowRedirectOptions: function(config, extras) {
    const httpState = this[$http];
    const path = extras && extras.path;
    const method = extras && extras.method;
    const auth = extras && extras.auth;
    const protocol = extras && extras.protocol;
    const beforeRedirect = extras && extras.beforeRedirect;

    const options = {
      path,
      method,
      headers: extras && extras.headers != null ? extras.headers : this.toJSON(),
      agents: { http: config && config.httpAgent, https: config && config.httpsAgent },
      auth,
      protocol,
      beforeRedirect,
      beforeRedirects: {}
    };

    if (config && config.socketPath) {
      options.socketPath = config.socketPath;
    } else if (extras && extras.parsed) {
      options.hostname = extras.parsed.hostname;
      options.port = extras.parsed.port;
    }

    httpState.options = options;
    httpState.protocol = protocol;
    return options;
  },

  selectHttpTransportKind: function(config, protocol) {
    const httpState = this[$http];
    const isHttpsRequest = /https:?/.test(protocol || httpState.protocol || '');
    let transportKind = 'follow';

    if (config && config.transport) {
      transportKind = 'custom';
    } else if (config && config.maxRedirects === 0) {
      transportKind = isHttpsRequest ? 'https' : 'http';
    } else if (isHttpsRequest) {
      transportKind = 'https-follow';
    } else {
      transportKind = 'http-follow';
    }

    httpState.transportKind = transportKind;
    httpState.protocol = protocol || httpState.protocol;
    return {isHttpsRequest, transportKind};
  },

  stripEmptyContentEncoding: function(resHeaders, data) {
    const httpState = this[$http];
    httpState.encoding = resHeaders && resHeaders['content-encoding'];

    if (!resHeaders) {
      return resHeaders;
    }

    if (data && data.length === 0 && resHeaders['content-encoding']) {
      delete resHeaders['content-encoding'];
      httpState.encoding = undefined;
    }

    return resHeaders;
  },

  decodeContentEncodingKind: function(resHeaders, decompress, brotliSupported) {
    const httpState = this[$http];
    const encoding = resHeaders && resHeaders['content-encoding'];
    httpState.encoding = encoding;

    if (decompress === false) {
      return {action: 'passthrough', encoding};
    }

    if (!encoding) {
      return {action: 'passthrough', encoding: undefined};
    }

    if (encoding === 'gzip' || encoding === 'compress' || encoding === 'deflate') {
      delete resHeaders['content-encoding'];
      httpState.encoding = undefined;
      return {action: 'unzip', encoding};
    }

    if (encoding === 'br') {
      if (brotliSupported) {
        delete resHeaders['content-encoding'];
        httpState.encoding = undefined;
        return {action: 'brotli', encoding};
      }
      return {action: 'passthrough', encoding};
    }

    return {action: 'passthrough', encoding};
  },

  parseSocketTimeout: function(config, req) {
    const httpState = this[$http];
    if (!config || !config.timeout) {
      httpState.timeout = null;
      return {timeout: null, error: null};
    }

    const timeout = parseInt(config.timeout, 10);
    if (isNaN(timeout)) {
      httpState.timeout = null;
      return {
        timeout: null,
        error: new AxiosError(
          'error trying to parse `config.timeout` to int',
          AxiosError.ERR_BAD_OPTION_VALUE,
          config,
          req
        )
      };
    }

    httpState.timeout = timeout;
    return {timeout, error: null};
  },

  applyProxyToHttpOptions: function(options, proxy, location) {
    const httpState = this[$http];
    httpState.options = options;
    httpState.path = location || (options && options.path);

    if (proxy) {
      if (proxy.username) {
        proxy.auth = (proxy.username || '') + ':' + (proxy.password || '');
      }

      if (proxy.auth) {
        if (proxy.auth.username || proxy.auth.password) {
          proxy.auth = (proxy.auth.username || '') + ':' + (proxy.auth.password || '');
        }
        const base64 = Buffer
          .from(proxy.auth, 'utf8')
          .toString('base64');
        options.headers['Proxy-Authorization'] = 'Basic ' + base64;
      }

      options.headers.host = options.hostname + (options.port ? ':' + options.port : '');
      options.hostname = proxy.hostname;
      options.host = proxy.hostname;
      options.port = proxy.port;
      options.path = location;
      if (proxy.protocol) {
        options.protocol = proxy.protocol;
      }
    }

    return options;
  },

  captureXhrSession: function(config) {
    const xhrState = this[$xhr];
    xhrState.config = config || null;
    xhrState.request = null;
    xhrState.requestData = config ? config.data : null;
    xhrState.responseType = config ? config.responseType : null;
    xhrState.fullPath = null;
    xhrState.protocol = null;
    xhrState.xsrfCookieName = config ? config.xsrfCookieName : null;
    xhrState.xsrfHeaderName = config ? config.xsrfHeaderName : null;
    xhrState.uploadProgress = null;
    xhrState.downloadProgress = null;
    return xhrState;
  },

  buildXhrProgressReducer: function(listener, isDownloadStream) {
    const xhrState = this[$xhr];
    const slot = {
      bytesNotified: 0,
      meter: speedometer(50, 250)
    };

    if (isDownloadStream) {
      xhrState.downloadProgress = slot;
    } else {
      xhrState.uploadProgress = slot;
    }

    return (e) => {
      const loaded = e.loaded;
      const total = e.lengthComputable ? e.total : undefined;
      const progressBytes = loaded - slot.bytesNotified;
      const rate = slot.meter(progressBytes);
      const inRange = loaded <= total;

      slot.bytesNotified = loaded;

      const data = {
        loaded,
        total,
        progress: total ? (loaded / total) : undefined,
        bytes: progressBytes,
        rate: rate ? rate : undefined,
        estimated: rate && total && inRange ? (total - loaded) / rate : undefined
      };

      data[isDownloadStream ? 'download' : 'upload'] = true;
      listener(data);
    };
  },

  resolveXhrUrl: function(config) {
    const xhrState = this[$xhr];
    const fullPath = buildFullPath(config && config.baseURL, config && config.url);
    xhrState.fullPath = fullPath;
    xhrState.protocol = parseProtocol(fullPath);
    const url = buildURL(fullPath, config && config.params, config && config.paramsSerializer);
    return {fullPath, url, protocol: xhrState.protocol};
  },

  shouldSendXsrf: function(config, fullPath) {
    const xhrState = this[$xhr];
    xhrState.fullPath = fullPath || xhrState.fullPath;
    xhrState.xsrfCookieName = config && config.xsrfCookieName;
    xhrState.xsrfHeaderName = config && config.xsrfHeaderName;

    if (!platform.isStandardBrowserEnv) {
      return false;
    }

    if (!config) {
      return false;
    }

    const sameOrigin = config.withCredentials || isURLSameOrigin(fullPath);
    if (!sameOrigin) {
      return false;
    }

    if (!config.xsrfCookieName) {
      return false;
    }

    return true;
  },

  configureXhrCredentials: function(request, config) {
    const xhrState = this[$xhr];
    xhrState.request = request;
    xhrState.config = config || xhrState.config;

    if (!request) {
      return request;
    }

    if (config) {
      request.timeout = config.timeout;
    }

    if (!utils.isUndefined(config && config.withCredentials)) {
      request.withCredentials = !!config.withCredentials;
    }

    return request;
  },

  configureXhrResponseType: function(request, config) {
    const xhrState = this[$xhr];
    const responseType = config && config.responseType;
    xhrState.responseType = responseType;
    xhrState.request = request;

    if (responseType && responseType !== 'json') {
      request.responseType = config.responseType;
    }

    return request;
  },

  validateRequestProtocol: function(fullPath, allowedProtocols) {
    const xhrState = this[$xhr];
    const protocol = parseProtocol(fullPath);
    xhrState.protocol = protocol;
    xhrState.fullPath = fullPath;

    if (protocol && allowedProtocols && allowedProtocols.indexOf(protocol) === -1) {
      return new AxiosError(
        'Unsupported protocol ' + protocol + ':',
        AxiosError.ERR_BAD_REQUEST,
        xhrState.config
      );
    }

    return null;
  },

  extractXhrResponsePayload: function(request, config) {
    const xhrState = this[$xhr];
    xhrState.request = request;
    const responseType = (config && config.responseType) || xhrState.responseType;

    if (!request) {
      return {data: undefined, status: 0, statusText: '', headers: this};
    }

    const responseData = !responseType || responseType === 'text' || responseType === 'json'
      ? request.responseText
      : request.response;

    return {
      data: responseData,
      status: request.status,
      statusText: request.statusText,
      headers: this,
      config,
      request
    };
  },

  bindXhrAbortHandler: function(config, request, reject) {
    const xhrState = this[$xhr];
    xhrState.config = config || xhrState.config;
    xhrState.request = request;

    return function onCanceled(cancel) {
      if (!request) {
        return;
      }
      reject(!cancel || cancel.type ? new CanceledError(null, config, request) : cancel);
      request.abort();
    };
  },

  composeXhrTimeoutError: function(config, request) {
    const xhrState = this[$xhr];
    xhrState.config = config || xhrState.config;
    xhrState.request = request;

    let timeoutErrorMessage = config && config.timeout
